def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if x == 1:
        return n == 1
    if x < 1 or n < 1:
        return False
    power = 0
    while n ** power <= x:
        if n ** power == x:
            return True
        power += 1
    return False

